verification_receipts.patch_excerpt:
diff --git a/scripts/test-executor-profiles.js b/scripts/test-executor-profiles.js
index 3178834..6e0daba 100644
--- a/scripts/test-executor-profiles.js
+++ b/scripts/test-executor-profiles.js
@@ -185,4 +185,40 @@ for (const forbidden of ['signature', 'private', 'raw_output', 'env', 'command',
 }
 assert.equal(replay.model_status, 'unknown');

+// Regression: telemetry that arrives with every other fact but no observed model
+// stays unknown on every surface. A verified receipt and trusted cost, duration,
+// and token counts are facts about the run, not about model identity, so they
+// must never promote a missing observation into a reported match.
+const verification = profiles.verifyForkReceiptWrapper(wrapper, { publicKey, expected: wrapperInput });
+assert.equal(verification.status, 'verified');
+const telemetry = { trusted: true, source: 'codex-jsonl', duration_ms: 1000, tokens: 900,
+  cost: { amount: 0.42, unit: 'usd', source: 'codex-jsonl' } };
+// A null-model profile is the only shape that can pass on observation alone, so
+// missing telemetry must be rejected before that branch is ever reached.
+const nullModel = legacy.find((entry) => entry.model === null);
+for (const absent of [{}, { model: null }, { model: '' }, { model: { id: 'qwen3-coder:30b' } }]) {
+  const observation = { ...telemetry, ...absent };
+  const label = JSON.stringify(absent);
+  assert.deepEqual(profiles.evaluateModelProof(local, observation), {
+    requested_model: local.model, observed_model: null,
+    status: 'unknown', reason_code: 'MODEL_OBSERVATION_MISSING',
+  }, label);
+  const state = profiles.missionControlExecutorState({ profile: local, observation, wrapper, verification });
+  assert.equal(state.observed_model, null, label);
+  assert.equal(state.model_status, 'unknown', label);
+  assert.equal(state.model_reason_code, 'MODEL_OBSERVATION_MISSING', label);
+  // The surrounding facts are known, so 'unknown' is a claim about the model alone.
+  assert.equal(state.receipt_status, 'verified', label);
+  assert.equal(state.cost_status, 'known', label);
+  assert.equal(state.duration_status, 'known', label);
+  assert.equal(state.tokens_status, 'known', label);
+  const missingReplay = profiles.publicExecutorReplay({ profile: local, observation, wrapper, verification });
+  assert.equal(missingReplay.observed_model, null, label);
+  assert.equal(missingReplay.model_status, 'unknown', label);
+  assert.deepEqual(profiles.evaluateModelProof(nullModel, observation), {
+    requested_model: 'default', observed_model: null,
+    status: 'unknown', reason_code: 'MODEL_OBSERVATION_MISSING',
+  }, label);
+}
+
 process.stdout.write('Executor profiles passed: strict profiles, canonical digests, literal invocations, bound receipts, and honest model proof.\n');
